static inline int linear_model_predict(const float *features, int length) {
    int best_class = 0;
    float best_score = -1e9f;

    for (int c = 0; c < LINEAR_NUM_CLASSES; c++) {
        float score = linear_biases[c];
        for (int j = 0; j < length; j++) {
            score += linear_weights[c][j] * features[j];
        }
        if (score > best_score) {
            best_score = score;
            best_class = c;
        }
    }
    return best_class;
}

